1: // Contract test for Lru. FROZEN: a solver must not modify this file.
2: #[path = "lib.rs"]
3: mod lib;
4: use lib::Lru;
5: 
6: #[test]
7: fn holds_what_fits() {
8:     let mut c = Lru::new(2);
9:     c.put("a", 1);
10:     c.put("b", 2);
11:     assert_eq!(c.get("a"), Some(1));
12:     assert_eq!(c.get("b"), Some(2));
13: }
14: 
15: #[test]
16: fn evicts_the_least_recently_used() {
17:     let mut c = Lru::new(2);
18:     c.put("a", 1);
19:     c.put("b", 2);
20:     c.put("c", 3); // evicts "a"
21:     assert_eq!(c.get("a"), None);
22:     assert_eq!(c.get("b"), Some(2));
23:     assert_eq!(c.get("c"), Some(3));
24: }
25: 
26: #[test]
27: fn a_read_counts_as_use() {
28:     let mut c = Lru::new(2);
29:     c.put("a", 1);
30:     c.put("b", 2);
31:     c.get("a"); // "a" is now the most recent, so "b" is next out
32:     c.put("c", 3);
33:     assert_eq!(c.get("b"), None);
34:     assert_eq!(c.get("a"), Some(1));
35: }
36: 
37: /// The invariant every operation must preserve: `keys()` and the stored entries
38: /// describe the same set, and neither ever exceeds the capacity.
39: #[test]
40: fn the_cache_never_exceeds_capacity() {
41:     let mut c = Lru::new(3);
42:     for (i, k) in ["a", "b", "c", "d", "e", "a", "f"].iter().enumerate() {
43:         c.put(k, i as i64);
44:         assert!(
45:             c.keys().len() <= 3,
46:             "after put({k}) the cache holds {:?}, over capacity",
47:             c.keys()
48:         );
49:     }
50: }

